const UPDATE_RUN_PHASES = [
	"requested",
	"staging",
	"validating",
	"repairing",
	"activating",
	"restarting",
	"verifying",
	"finished"
];
const UPDATE_RUN_STATUSES = [
	"running",
	"succeeded",
	"failed",
	"rolled-back",
	"skipped"
];
const UPDATE_RUN_TRIGGERS = [
	"chat",
	"control-ui",
	"cli",
	"campaign",
	"mac-app",
	"api"
];
const UPDATE_RUN_STEP_STATUSES = [
	"pending",
	"in_progress",
	"completed",
	"failed",
	"skipped"
];
